{"module_source":""""Python port of CBTRN02C: post daily transactions or route them to the rejects file."""
from decimal import Decimal

from port.runtime import Abend, fit, rule


DESC_WIDTH = 76


def _new_state():
    # Fail reason reset to 0 and description to spaces before each validation.
    return {"reason": 0, "desc": " " * DESC_WIDTH}


def _set_fail(state, code, desc):
    state["reason"] = code
    state["desc"] = desc.ljust(DESC_WIDTH)[:DESC_WIDTH]


@rule("BR-CBTRN02C-001")
def lookup_card_xref(ctx, tran, state):
    """Look up the card in the cross-reference; reason 100 if not found."""
    xref = ctx.xref_by_card.get(tran["DALYTRAN-CARD-NUM"])
    if xref is None:
        _set_fail(state, 100, "INVALID CARD NUMBER FOUND")
    return xref


@rule("BR-CBTRN02C-002")
def lookup_account(ctx, xref, state):
    """Read the account by the cross-referenced account ID; reason 101 if missing."""
    account = ctx.accounts.get(xref["XREF-ACCT-ID"])
    if account is None:
        _set_fail(state, 101, "ACCOUNT RECORD NOT FOUND")
    return account


@rule("BR-CBTRN02C-003")
def check_credit_limit(account, tran, state):
    """Projected balance (stored S9(9)V99) above credit limit -> reason 102."""
    temp_bal = fit(
        account["ACCT-CURR-CYC-CREDIT"]
        - account["ACCT-CURR-CYC-DEBIT"]
        + tran["DALYTRAN-AMT"],
        11, 2, True,
    )
    if account["ACCT-CREDIT-LIMIT"] < temp_bal:
        _set_fail(state, 102, "OVERLIMIT TRANSACTION")


@rule("BR-CBTRN02C-004")
def check_expiration(account, tran, state):
    """Expiration date earlier than origination date -> reason 103 (overrides 102)."""
    # GAP: comparison uses Python code-point ordering of the characters.
    if account["ACCT-EXPIRAION-DATE"] < tran["DALYTRAN-ORIG-TS"][0:10]:
        _set_fail(state, 103, "TRANSACTION RECEIVED AFTER ACCT EXPIRATION")


def validate_transaction(ctx, tran, state):
    xref = lookup_card_xref(ctx, tran, state)
    account = None
    if state["reason"] == 0:
        account = lookup_account(ctx, xref, state)
        if account is not None:
            check_credit_limit(account, tran, state)
            check_expiration(account, tran, state)
    return xref, account


@rule("BR-CBTRN02C-006")
def update_category_balance(ctx, xref, tran):
    """Create or increase the transaction-category balance by the posted amount."""
    key = (xref["XREF-ACCT-ID"], tran["DALYTRAN-TYPE-CD"], tran["DALYTRAN-CAT-CD"])
    existing = ctx.category_balances.get(key)
    create_flag = "Y" if existing is None else "N"
    if create_flag == "Y":
        record = {
            "TRANCAT-ACCT-ID": xref["XREF-ACCT-ID"],
            "TRANCAT-TYPE-CD": tran["DALYTRAN-TYPE-CD"],
            "TRANCAT-CD": tran["DALYTRAN-CAT-CD"],
            "TRAN-CAT-BAL": fit(Decimal("0") + tran["DALYTRAN-AMT"], 11, 2, True),
            "FILLER": " " * 22,
        }
        ctx.category_balances[key] = record
    else:
        existing["TRAN-CAT-BAL"] = fit(
            existing["TRAN-CAT-BAL"] + tran["DALYTRAN-AMT"], 11, 2, True
        )
        ctx.category_balances[key] = existing


@rule("BR-CBTRN02C-007")
def update_account(ctx, xref, account, tran, state):
    """Add the amount to current balance and to cycle credit or cycle debit."""
    amt = tran["DALYTRAN-AMT"]
    account["ACCT-CURR-BAL"] = fit(account["ACCT-CURR-BAL"] + amt, 12, 2, True)
    if amt >= 0:
        account["ACCT-CURR-CYC-CREDIT"] = fit(
            account["ACCT-CURR-CYC-CREDIT"] + amt, 12, 2, True
        )
    else:
        account["ACCT-CURR-CYC-DEBIT"] = fit(
            account["ACCT-CURR-CYC-DEBIT"] + amt, 12, 2, True
        )
    acct_id = xref["XREF-ACCT-ID"]
    if acct_id not in ctx.accounts:
        _set_fail(state, 109, "ACCOUNT RECORD NOT FOUND")
    else:
        ctx.accounts[acct_id] = account


def write_transaction_record(ctx, tran):
    # GAP: no rule specifies how TRAN-RECORD is built; each DALYTRAN-* field is
    # copied to the matching TRAN-* field, including TRAN-PROC-TS (ctx.now() unused).
    names = [
        "ID", "TYPE-CD", "CAT-CD", "SOURCE", "DESC", "AMT", "MERCHANT-ID",
        "MERCHANT-NAME", "MERCHANT-CITY", "MERCHANT-ZIP", "CARD-NUM",
        "ORIG-TS", "PROC-TS",
    ]
    record = {}
    for name in names:
        record["TRAN-" + name] = tran["DALYTRAN-" + name]
    record["FILLER"] = " " * 20
    # GAP: a duplicate key is assumed to be raised as Abend by ctx.write_transaction;
    # any other exception it raises is converted to Abend.
    try:
        ctx.write_transaction(record)
    except Abend:
        raise
    except Exception as exc:
        raise Abend(str(exc))


def post_transaction(ctx, xref, account, tran, state):
    update_category_balance(ctx, xref, tran)
    update_account(ctx, xref, account, tran, state)
    write_transaction_record(ctx, tran)


@rule("BR-CBTRN02C-005")
def process_daily_transactions(ctx):
    """Validate each record, post or reject it, report counts and set RC 4."""
    transaction_count = 0
    reject_count = 0
    for tran in ctx.daily_transactions:
        transaction_count += 1
        state = _new_state()
        xref, account = validate_transaction(ctx, tran, state)
        if state["reason"] == 0:
            post_transaction(ctx, xref, account, tran, state)
        else:
            reject_count += 1
            ctx.write_reject(tran, fit(state["reason"], 4, 0, False), state["desc"])
    # GAP: display format of the counts is unspecified; label followed by the number.
    print("TRANSACTIONS PROCESSED :" + str(transaction_count))
    print("TRANSACTIONS REJECTED  :" + str(reject_count))
    if reject_count > 0:
        ctx.return_code = 4


def run(ctx) -> None:
    process_daily_transactions(ctx)
